input.sparql:
SELECT ?zone ?label WHERE {
  ?zone a brick:Room .
  ?zone rdfs:label ?label .
  FILTER(CONTAINS(LCASE(?label), "perimeter") && CONTAINS(LCASE(?label), "mid") && CONTAINS(LCASE(?label), "zn_3"))
}

SELECT ?point ?cls ?ts_id ?label WHERE {
  ?point brick:isPointOf <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z02> .
  ?point a ?cls .
  OPTIONAL { ?point ref:hasTimeseriesId ?ts_id }
  OPTIONAL { ?point rdfs:label ?label }
}

SELECT ?p ?ref ?ts WHERE {
  ?p brick:isPointOf <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z02> .
  ?p a brick:Occupancy_Sensor .
  OPTIONAL { ?p ref:hasExternalReference ?ref }
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
}
